 parser=argparse.ArgumentParser();parser.add_argument('--public',action='store_true');parser.add_argument('--attempt',type=int,default=1);args=parser.parse_args();kind='public' if args.public else 'lab';work=ROOT/f'references-local/voice-assembly-{kind}{args.attempt:02d}';out=f'evidence/voice_assembly_{kind}{args.attempt:02d}.json';require(not work.exists() and not (ROOT/out).exists(),'exclusive measured candidate');inp=json.loads((ROOT/'evidence/voice_assembly_inputs03.json').read_text(encoding='utf8'));require(inp['passed'],'admitted inputs');names=set(RUST)|{'tools/assembly_vco_helper.rs','tools/run_assembly_voice.py','tools/prepare_assembly_voice.py','docs/VOZ_ENSAMBLADO_PROTOCOLO.md','evidence/voice_assembly_inputs03.json'}
 if args.public:names|={p.relative_to(ROOT).as_posix() for p in (ROOT/'crates/rf-d-circuit/src').rglob('*.rs')}|{'evidence/voice_assembly_promotion01.json'}
